module axixclk #(
		parameter integer C_S_AXI_ID_WIDTH	= 2,
		parameter integer C_S_AXI_DATA_WIDTH	= 32,
		parameter integer C_S_AXI_ADDR_WIDTH	= 6,
		parameter [0:0]	OPT_WRITE_ONLY = 1'b0,
		parameter [0:0]	OPT_READ_ONLY = 1'b0,
		parameter	XCLOCK_FFS = 2,
		parameter	LGFIFO = 5
	) (
		input	wire				S_AXI_ACLK,
		input	wire				S_AXI_ARESETN,
		input	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_AWID,
		input	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	S_AXI_AWADDR,
		input	wire [7 : 0]			S_AXI_AWLEN,
		input	wire [2 : 0]			S_AXI_AWSIZE,
		input	wire [1 : 0]			S_AXI_AWBURST,
		input	wire				S_AXI_AWLOCK,
		input	wire [3 : 0]			S_AXI_AWCACHE,
		input	wire [2 : 0]			S_AXI_AWPROT,
		input	wire [3 : 0]			S_AXI_AWQOS,
		input	wire				S_AXI_AWVALID,
		output	wire				S_AXI_AWREADY,
		input	wire [C_S_AXI_DATA_WIDTH-1 : 0]	S_AXI_WDATA,
		input	wire [(C_S_AXI_DATA_WIDTH/8)-1 : 0] S_AXI_WSTRB,
		input	wire				S_AXI_WLAST,
		input	wire				S_AXI_WVALID,
		output	wire				S_AXI_WREADY,
		output	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_BID,
		output	wire [1 : 0]			S_AXI_BRESP,
		output	wire				S_AXI_BVALID,
		input	wire				S_AXI_BREADY,
		input	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_ARID,
		input	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	S_AXI_ARADDR,
		input	wire [7 : 0]			S_AXI_ARLEN,
		input	wire [2 : 0]			S_AXI_ARSIZE,
		input	wire [1 : 0]			S_AXI_ARBURST,
		input	wire				S_AXI_ARLOCK,
		input	wire [3 : 0]			S_AXI_ARCACHE,
		input	wire [2 : 0]			S_AXI_ARPROT,
		input	wire [3 : 0]			S_AXI_ARQOS,
		input	wire				S_AXI_ARVALID,
		output	wire				S_AXI_ARREADY,
		output	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_RID,
		output	wire [C_S_AXI_DATA_WIDTH-1 : 0]	S_AXI_RDATA,
		output	wire [1 : 0]			S_AXI_RRESP,
		output	wire				S_AXI_RLAST,
		output	wire				S_AXI_RVALID,
		input	wire				S_AXI_RREADY,
		input	wire				M_AXI_ACLK,
		output	wire				M_AXI_ARESETN,
		output	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_AWID,
		output	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	M_AXI_AWADDR,
		output	wire [7 : 0]			M_AXI_AWLEN,
		output	wire [2 : 0]			M_AXI_AWSIZE,
		output	wire [1 : 0]			M_AXI_AWBURST,
		output	wire				M_AXI_AWLOCK,
		output	wire [3 : 0]			M_AXI_AWCACHE,
		output	wire [2 : 0]			M_AXI_AWPROT,
		output	wire [3 : 0]			M_AXI_AWQOS,
		output	wire				M_AXI_AWVALID,
		input	wire				M_AXI_AWREADY,
		output	wire [C_S_AXI_DATA_WIDTH-1 : 0]	M_AXI_WDATA,
		output	wire [(C_S_AXI_DATA_WIDTH/8)-1 : 0] M_AXI_WSTRB,
		output	wire				M_AXI_WLAST,
		output	wire				M_AXI_WVALID,
		input	wire				M_AXI_WREADY,
		input	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_BID,
		input	wire [1 : 0]			M_AXI_BRESP,
		input	wire				M_AXI_BVALID,
		output	wire				M_AXI_BREADY,
		output	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_ARID,
		output	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	M_AXI_ARADDR,
		output	wire [7 : 0]			M_AXI_ARLEN,
		output	wire [2 : 0]			M_AXI_ARSIZE,
		output	wire [1 : 0]			M_AXI_ARBURST,
		output	wire				M_AXI_ARLOCK,
		output	wire [3 : 0]			M_AXI_ARCACHE,
		output	wire [2 : 0]			M_AXI_ARPROT,
		output	wire [3 : 0]			M_AXI_ARQOS,
		output	wire				M_AXI_ARVALID,
		input	wire				M_AXI_ARREADY,
		input	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_RID,
		input	wire [C_S_AXI_DATA_WIDTH-1 : 0]	M_AXI_RDATA,
		input	wire [1 : 0]			M_AXI_RRESP,
		input	wire				M_AXI_RLAST,
		input	wire				M_AXI_RVALID,
		output	wire				M_AXI_RREADY
	);

	// Local parameters
	localparam integer AW_FIFO_DEPTH = 2**LGFIFO;
	localparam integer AW_FIFO_PTR_WIDTH = LGFIFO;
	localparam integer W_FIFO_DEPTH = 2**LGFIFO;
	localparam integer W_FIFO_PTR_WIDTH = LGFIFO;
	localparam integer B_FIFO_DEPTH = 2**LGFIFO;
	localparam integer B_FIFO_PTR_WIDTH = LGFIFO;
	localparam integer AR_FIFO_DEPTH = 2**LGFIFO;
	localparam integer AR_FIFO_PTR_WIDTH = LGFIFO;
	localparam integer R_FIFO_DEPTH = 2**LGFIFO;
	localparam integer R_FIFO_PTR_WIDTH = LGFIFO;

	// Reset synchronization
	reg [1:0] m_reset_sync;
	reg m_reset_sync_next;
	always @(posedge M_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			m_reset_sync <= 2'b00;
		end else begin
			m_reset_sync <= {m_reset_sync[0], 1'b1};
		end
	end
	assign M_AXI_ARESETN = m_reset_sync[1];

	// AW channel: S to M
	reg [AW_FIFO_DEPTH-1:0] aw_valid_s;
	reg [AW_FIFO_DEPTH-1:0] aw_valid_m;
	reg [AW_FIFO_PTR_WIDTH-1:0] aw_wr_ptr_s;
	reg [AW_FIFO_PTR_WIDTH-1:0] aw_rd_ptr_s;
	reg [AW_FIFO_PTR_WIDTH-1:0] aw_wr_ptr_m;
	reg [AW_FIFO_PTR_WIDTH-1:0] aw_rd_ptr_m;
	reg [C_S_AXI_ID_WIDTH-1:0] aw_id_s [0:AW_FIFO_DEPTH-1];
	reg [C_S_AXI_ADDR_WIDTH-1:0] aw_addr_s [0:AW_FIFO_DEPTH-1];
	reg [7:0] aw_len_s [0:AW_FIFO_DEPTH-1];
	reg [2:0] aw_size_s [0:AW_FIFO_DEPTH-1];
	reg [1:0] aw_burst_s [0:AW_FIFO_DEPTH-1];
	reg aw_lock_s [0:AW_FIFO_DEPTH-1];
	reg [3:0] aw_cache_s [0:AW_FIFO_DEPTH-1];
	reg [2:0] aw_prot_s [0:AW_FIFO_DEPTH-1];
	reg [3:0] aw_qos_s [0:AW_FIFO_DEPTH-1];

	// AW FIFO write (S clock)
	wire aw_wr_en_s = S_AXI_AWVALID && S_AXI_AWREADY;
	assign S_AXI_AWREADY = !aw_valid_s[aw_wr_ptr_s];

	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			aw_valid_s <= {AW_FIFO_DEPTH{1'b0}};
			aw_wr_ptr_s <= {AW_FIFO_PTR_WIDTH{1'b0}};
			aw_rd_ptr_s <= {AW_FIFO_PTR_WIDTH{1'b0}};
		end else begin
			if (aw_wr_en_s) begin
				aw_valid_s[aw_wr_ptr_s] <= 1'b1;
				aw_id_s[aw_wr_ptr_s] <= S_AXI_AWID;
				aw_addr_s[aw_wr_ptr_s] <= S_AXI_AWADDR;
				aw_len_s[aw_wr_ptr_s] <= S_AXI_AWLEN;
				aw_size_s[aw_wr_ptr_s] <= S_AXI_AWSIZE;
				aw_burst_s[aw_wr_ptr_s] <= S_AXI_AWBURST;
				aw_lock_s[aw_wr_ptr_s] <= S_AXI_AWLOCK;
				aw_cache_s[aw_wr_ptr_s] <= S_AXI_AWCACHE;
				aw_prot_s[aw_wr_ptr_s] <= S_AXI_AWPROT;
				aw_qos_s[aw_wr_ptr_s] <= S_AXI_AWQOS;
				aw_wr_ptr_s <= aw_wr_ptr_s + 1'b1;
			end
			if (aw_valid_s[aw_rd_ptr_s] && M_AXI_AWREADY) begin
				aw_valid_s[aw_rd_ptr_s] <= 1'b0;
				aw_rd_ptr_s <= aw_rd_ptr_s + 1'b1;
			end
		end
	end

	// AW FIFO read (M clock)
	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN) begin
			aw_valid_m <= {AW_FIFO_DEPTH{1'b0}};
			aw_wr_ptr_m <= {AW_FIFO_PTR_WIDTH{1'b0}};
			aw_rd_ptr_m <= {AW_FIFO_PTR_WIDTH{1'b0}};
		end else begin
			// Synchronize write pointer
			aw_wr_ptr_m <= aw_wr_ptr_s;
			// Update valid bits based on synchronized pointers
			// This is a simplified approach; in practice, you'd use a proper async FIFO
			// For this implementation, we'll use a different strategy
		end
	end

	// Simplified AW bridge using direct synchronization
	reg [C_S_AXI_ID_WIDTH-1:0] aw_id_m;
	reg [C_S_AXI_ADDR_WIDTH-1:0] aw_addr_m;
	reg [7:0] aw_len_m;
	reg [2:0] aw_size_m;
	reg [1:0] aw_burst_m;
	reg aw_lock_m;
	reg [3:0] aw_cache_m;
	reg [2:0] aw_prot_m;
	reg [3:0] aw_qos_m;
	reg aw_valid_m;

	// Synchronize AW signals
	reg [C_S_AXI_ID_WIDTH-1:0] aw_id_sync1, aw_id_sync2;
	reg [C_S_AXI_ADDR_WIDTH-1:0] aw_addr_sync1, aw_addr_sync2;
	reg [7:0] aw_len_sync1, aw_len_sync2;
	reg [2:0] aw_size_sync1, aw_size_sync2;
	reg [1:0] aw_burst_sync1, aw_burst_sync2;
	reg aw_lock_sync1, aw_lock_sync2;
	reg [3:0] aw_cache_sync1, aw_cache_sync2;
	reg [2:0] aw_prot_sync1, aw_prot_sync2;
	reg [3:0] aw_qos_sync1, aw_qos_sync2;
	reg aw_valid_sync1, aw_valid_sync2;

	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			aw_id_sync1 <= {C_S_AXI_ID_WIDTH{1'b0}};
			aw_addr_sync1 <= {C_S_AXI_ADDR_WIDTH{1'b0}};
			aw_len_sync1 <= 8'b0;
			aw_size_sync1 <= 3'b0;
			aw_burst_sync1 <= 2'b0;
			aw_lock_sync1 <= 1'b0;
			aw_cache_sync1 <= 4'b0;
			aw_prot_sync1 <= 3'b0;
			aw_qos_sync1 <= 4'b0;
			aw_valid_sync1 <= 1'b0;
		end else begin
			aw_id_sync1 <= S_AXI_AWID;
			aw_addr_sync1 <= S_AXI_AWADDR;
			aw_len_sync1 <= S_AXI_AWLEN;
			aw_size_sync1 <= S_AXI_AWSIZE;
			aw_burst_sync1 <= S_AXI_AWBURST;
			aw_lock_sync1 <= S_AXI_AWLOCK;
			aw_cache_sync1 <= S_AXI_AWCACHE;
			aw_prot_sync1 <= S_AXI_AWPROT;
			aw_qos_sync1 <= S_AXI_AWQOS;
			aw_valid_sync1 <= S_AXI_AWVALID;
		end
	end

	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN) begin
			aw_id_sync2 <= {C_S_AXI_ID_WIDTH{1'b0}};
			aw_addr_sync2 <= {C_S_AXI_ADDR_WIDTH{1'b0}};
			aw_len_sync2 <= 8'b0;
			aw_size_sync2 <= 3'b0;
			aw_burst_sync2 <= 2'b0;
			aw_lock_sync2 <= 1'b0;
			aw_cache_sync2 <= 4'b0;
			aw_prot_sync2 <= 3'b0;
			aw_qos_sync2 <= 4'b0;
			aw_valid_sync2 <= 1'b0;
			aw_id_m <= {C_S_AXI_ID_WIDTH{1'b0}};
			aw_addr_m <= {C_S_AXI_ADDR_WIDTH{1'b0}};
			aw_len_m <= 8'b0;
			aw_size_m <= 3'b0;
			aw_burst_m <= 2'b0;
			aw_lock_m <= 1'b0;
			aw_cache_m <= 4'b0;
			aw_prot_m <= 3'b0;
			aw_qos_m <= 4'b0;
			aw_valid_m <= 1'b0;
		end else begin
			aw_id_sync2 <= aw_id_sync1;
			aw_addr_sync2 <= aw_addr_sync1;
			aw_len_sync2 <= aw_len_sync1;
			aw_size_sync2 <= aw_size_sync1;
			aw_burst_sync2 <= aw_burst_sync1;
			aw_lock_sync2 <= aw_lock_sync1;
			aw_cache_sync2 <= aw_cache_sync1;
			aw_prot_sync2 <= aw_prot_sync1;
			aw_qos_sync2 <= aw_qos_sync1;
			aw_valid_sync2 <= aw_valid_sync1;

			if (aw_valid_sync2 && !aw_valid_m) begin
				aw_id_m <= aw_id_sync2;
				aw_addr_m <= aw_addr_sync2;
				aw_len_m <= aw_len_sync2;
				aw_size_m <= aw_size_sync2;
				aw_burst_m <= aw_burst_sync2;
				aw_lock_m <= aw_lock_sync2;
				aw_cache_m <= aw_cache_sync2;
				aw_prot_m <= aw_prot_sync2;
				aw_qos_m <= aw_qos_sync2;
				aw_valid_m <= 1'b1;
			end else if (aw_valid_m && M_AXI_AWREADY) begin
				aw_valid_m <= 1'b0;
			end
		end
	end

	assign M_AXI_AWID = aw_id_m;
	assign M_AXI_AWADDR = aw_addr_m;
	assign M_AXI_AWLEN = aw_len_m;
	assign M_AXI_AWSIZE = aw_size_m;
	assign M_AXI_AWBURST = aw_burst_m;
	assign M_AXI_AWLOCK = aw_lock_m;
	assign M_AXI_AWCACHE = aw_cache_m;
	assign M_AXI_AWPROT = aw_prot_m;
	assign M_AXI_AWQOS = aw_qos_m;
	assign M_AXI_AWVALID = aw_valid_m;

	// W channel: S to M
	reg [C_S_AXI_DATA_WIDTH-1:0] wdata_m;
	reg [(C_S_AXI_DATA_WIDTH/8)-1:0] wstrb_m;
	reg wlast_m;
	reg wvalid_m;
	reg wdata_reg;
	reg wstrb_reg;
	reg wlast_reg;

	reg [C_S_AXI_DATA_WIDTH-1:0] wdata_sync1, wdata_sync2;
	reg [(C_S_AXI_DATA_WIDTH/8)-1:0] wstrb_sync1, wstrb_sync2;
	reg wlast_sync1, wlast_sync2;
	reg wvalid_sync1, wvalid_sync2;

	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			wdata_sync1 <= {C_S_AXI_DATA_WIDTH{1'b0}};
			wstrb_sync1 <= {(C_S_AXI_DATA_WIDTH/8){1'b0}};
			wlast_sync1 <= 1'b0;
			wvalid_sync1 <= 1'b0;
		end else begin
			wdata_sync1 <= S_AXI_WDATA;
			wstrb_sync1 <= S_AXI_WSTRB;
			wlast_sync1 <= S_AXI_WLAST;
			wvalid_sync1 <= S_AXI_WVALID;
		end
	end

	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN) begin
			wdata_sync2 <= {C_S_AXI_DATA_WIDTH{1'b0}};
			wstrb_sync2 <= {(C_S_AXI_DATA_WIDTH/8){1'b0}};
			wlast_sync2 <= 1'b0;
			wvalid_sync2 <= 1'b0;
			wdata_m <= {C_S_AXI_DATA_WIDTH{1'b0}};
			wstrb_m <= {(C_S_AXI_DATA_WIDTH/8){1'b0}};
			wlast_m <= 1'b0;
			wvalid_m <= 1'b0;
			wdata_reg <= {C_S_AXI_DATA_WIDTH{1'b0}};
			wstrb_reg <= {(C_S_AXI_DATA_WIDTH/8){1'b0}};
			wlast_reg <= 1'b0;
		end else begin
			wdata_sync2 <= wdata_sync1;
			wstrb_sync2 <= wstrb_sync1;
			wlast_sync2 <= wlast_sync1;
			wvalid_sync2 <= wvalid_sync1;

			// Hold one extra M_AXI clock before M_AXI_WVALID
			if (wvalid_sync2 && !wvalid_m) begin
				wdata_reg <= wdata_sync2;
				wstrb_reg <= wstrb_sync2;
				wlast_reg <= wlast_sync2;
				wvalid_m <= 1'b1;
			end else if (wvalid_m && M_AXI_WREADY) begin
				wvalid_m <= 1'b0;
			end
		end
	end

	assign M_AXI_WDATA = wdata_reg;
	assign M_AXI_WSTRB = wstrb_reg;
	assign M_AXI_WLAST = wlast_reg;
	assign M_AXI_WVALID = wvalid_m;

	// B channel: M to S
	reg [C_S_AXI_ID_WIDTH-1:0] bid_s;
	reg [1:0] bresp_s;
	reg bvalid_s;

	reg [C_S_AXI_ID_WIDTH-1:0] bid_sync1, bid_sync2;
	reg [1:0] bresp_sync1, bresp_sync2;
	reg bvalid_sync1, bvalid_sync2;

	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN) begin
			bid_sync1 <= {C_S_AXI_ID_WIDTH{1'b0}};
			bresp_sync1 <= 2'b0;
			bvalid_sync1 <= 1'b0;
		end else begin
			bid_sync1 <= M_AXI_BID;
			bresp_sync1 <= M_AXI_BRESP;
			bvalid_sync1 <= M_AXI_BVALID;
		end
	end

	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			bid_sync2 <= {C_S_AXI_ID_WIDTH{1'b0}};
			bresp_sync2 <= 2'b0;
			bvalid_sync2 <= 1'b0;
			bid_s <= {C_S_AXI_ID_WIDTH{1'b0}};
			bresp_s <= 2'b0;
			bvalid_s <= 1'b0;
		end else begin
			bid_sync2 <= bid_sync1;
			bresp_sync2 <= bresp_sync1;
			bvalid_sync2 <= bvalid_sync1;

			if (bvalid_sync2 && !bvalid_s) begin
				bid_s <= bid_sync2;
				bresp_s <= bresp_sync2;
				bvalid_s <= 1'b1;
			end else if (bvalid_s && S_AXI_BREADY) begin
				bvalid_s <= 1'b0;
			end
		end
	end

	assign S_AXI_BID = bid_s;
	assign S_AXI_BRESP = bresp_s;
	assign S_AXI_BVALID = bvalid_s;
	assign M_AXI_BREADY = bvalid_sync1;

	// AR channel: S to M
	reg [C_S_AXI_ID_WIDTH-1:0] arid_m;
	reg [C_S_AXI_ADDR_WIDTH-1:0] araddr_m;
	reg [7:0] arlen_m;
	reg [2:0] arsize_m;
	reg [1:0] arburst_m;
	reg arlock_m;
	reg [3:0] arcache_m;
	reg [2:0] arprot_m;
	reg [3:0] arqos_m;
	reg arvalid_m;

	reg [C_S_AXI_ID_WIDTH-1:0] arid_sync1, arid_sync2;
	reg [C_S_AXI_ADDR_WIDTH-1:0] araddr_sync1, araddr_sync2;
	reg [7:0] arlen_sync1, arlen_sync2;
	reg [2:0] arsize_sync1, arsize_sync2;
	reg [1:0] arburst_sync1, arburst_sync2;
	reg arlock_sync1, arlock_sync2;
	reg [3:0] arcache_sync1, arcache_sync2;
	reg [2:0] arprot_sync1, arprot_sync2;
	reg [3:0] arqos_sync1, arqos_sync2;
	reg arvalid_sync1, arvalid_sync2;

	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			arid_sync1 <= {C_S_AXI_ID_WIDTH{1'b0}};
			araddr_sync1 <= {C_S_AXI_ADDR_WIDTH{1'b0}};
			arlen_sync1 <= 8'b0;
			arsize_sync1 <= 3'b0;
			arburst_sync1 <= 2'b0;
			arlock_sync1 <= 1'b0;
			arcache_sync1 <= 4'b0;
			arprot_sync1 <= 3'b0;
			arqos_sync1 <= 4'b0;
			arvalid_sync1 <= 1'b0;
		end else begin
			arid_sync1 <= S_AXI_ARID;
			araddr_sync1 <= S_AXI_ARADDR;
			arlen_sync1 <= S_AXI_ARLEN;
			arsize_sync1 <= S_AXI_ARSIZE;
			arburst_sync1 <= S_AXI_ARBURST;
			arlock_sync1 <= S_AXI_ARLOCK;
			arcache_sync1 <= S_AXI_ARCACHE;
			arprot_sync1 <= S_AXI_ARPROT;
			arqos_sync1 <= S_AXI_ARQOS;
			arvalid_sync1 <= S_AXI_ARVALID;
		end
	end

	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN) begin
			arid_sync2 <= {C_S_AXI_ID_WIDTH{1'b0}};
			araddr_sync2 <= {C_S_AXI_ADDR_WIDTH{1'b0}};
			arlen_sync2 <= 8'b0;
			arsize_sync2 <= 3'b0;
			arburst_sync2 <= 2'b0;
			arlock_sync2 <= 1'b0;
			arcache_sync2 <= 4'b0;
			arprot_sync2 <= 3'b0;
